-- 20261122000002_odai_seed_catalog.sql — demo catalog for the seed tenant (idempotent upsert; run under service/migration role)
ON CONFLICT (tenant_id, sku) DO UPDATE SET name=excluded.name, category=excluded.category, package=excluded.package, currency=excluded.currency, website_price=excluded.website_price, price_type=excluded.price_type, reseller_authorized=excluded.reseller_authorized, regulatory_review_status=excluded.regulatory_review_status, fulfillment_mode=excluded.fulfillment_mode, marketing_claims_approved=excluded.marketing_claims_approved, review_state=excluded.review_state, provenance=excluded.provenance;
